const fs=require('node:fs'),crypto=require('node:crypto'),{spawnSync}=require('node:child_process');
const root='/tmp/askk-max-opt-native';
fs.mkdirSync(root+'/pages',{recursive:true});
const files={
 'package.json':JSON.stringify({private:true,scripts:{build:'next build --webpack'},dependencies:{next:'16.3.6',react:'19.3.0','react-dom':'19.3.0'}}),
 'next.config.mjs':'export default {output:"export",images:{unoptimized:true},experimental:{cpus:1,webpackBuildWorker:false}}',
 'pages/index.js':'import React from "react";export default function Page(){return React.createElement("main",null,"Browser Linux build proof")}'
};
for(const [name,content] of Object.entries(files))fs.writeFileSync(root+'/'+name,content);
const proof={runtime:{node:process.version,arch:process.arch,v8:process.versions.v8,uid:process.getuid(),nodeSha256:crypto.createHash('sha256').update(fs.readFileSync(process.execPath)).digest('hex')},files:Object.fromEntries(Object.entries(files).map(([name,content])=>[name,{content,sha256:crypto.createHash('sha256').update(content).digest('hex')}])),profile:'--max-opt=0; JS functions limited to Ignition; normal WebAssembly and RegExp code generation remain enabled'};
const env={...process.env,NODE_ENV:'production',NEXT_TELEMETRY_DISABLED:'1',NODE_DISABLE_COMPILE_CACHE:'1',DEBUG:'next:build:webpack-build'};
function run(name,args){const start=performance.now();const result=spawnSync('node',args,{cwd:root,env,encoding:'utf8',timeout:180000,maxBuffer:4*1024*1024});proof[name]={args,status:result.status,signal:result.signal,stdout:result.stdout,stderr:result.stderr,error:result.error?.message,milliseconds:performance.now()-start};if(result.status!==0)throw new Error(name+' failed');}
try{
run('prepare',['/opt/harness/prepare-template.js']);
run('hashPreflight',['--max-opt=0','-e',
 'const w=require("/opt/harness/template/node_modules/next/dist/compiled/webpack/webpack");const expected={xxhash64:"ef46db3751d8e999",md4:"31d6cfe0d16ae931b73c59d7e0c089c0"};const hashes={};for(const [name,digest]of Object.entries(expected)){hashes[name]=w.webpack.util.createHash(name).update("").digest("hex");if(hashes[name]!==digest)throw new Error(name+" mismatch")}if(typeof WebAssembly!=="object")throw new Error("WebAssembly unavailable");console.log(JSON.stringify({wasm:typeof WebAssembly,hashes,execArgv:process.execArgv.slice(0,1)}))']);
run('nextBuild',['--max-opt=0','node_modules/next/dist/bin/next','build','--webpack']);
const html=fs.readFileSync(root+'/out/index.html');if(!html.includes('Browser Linux build proof'))throw new Error('Missing artifact text');proof.artifact={bytes:html.length,sha256:crypto.createHash('sha256').update(html).digest('hex')};proof.passed=true;
}catch(error){proof.error=String(error);proof.passed=false}
console.log(JSON.stringify(proof));process.exitCode=proof.passed?0:1;
